import{_ as a,o as r,c as i,a2 as o}from"./chunks/framework.DpXDHk3d.js";const T=JSON.parse('{"title":"9.2 低压配电系统的接地形式","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/09-chapter-9-di-ya-pei-dian-xi-tong/9-2-di-ya-pei-dian-xi-tong-de-jie-di-xing-shi.md","filePath":"electrician/low-voltage-electrician/09-chapter-9-di-ya-pei-dian-xi-tong/9-2-di-ya-pei-dian-xi-tong-de-jie-di-xing-shi.md","lastUpdated":1793095197000}'),n={name:"electrician/low-voltage-electrician/09-chapter-9-di-ya-pei-dian-xi-tong/9-2-di-ya-pei-dian-xi-tong-de-jie-di-xing-shi.md"};function e(d,t,l,s,h,g){return r(),i("div",null,[...t[0]||(t[0]=[o(`<h1 id="_9-2-低压配电系统的接地形式" tabindex="-1">9.2 低压配电系统的接地形式 <a class="header-anchor" href="#_9-2-低压配电系统的接地形式" aria-label="Permalink to &quot;9.2 低压配电系统的接地形式&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>低压配电系统按&quot;电源中性点怎么接地、设备外壳怎么保护&quot;分成 TN、TT、IT 三种形式。看懂这些字母的意思,记住最常见的 <strong>TN-S(三相五线制)</strong>,是本章必考内容。</p><h2 id="一、字母的含义-必背" tabindex="-1">一、字母的含义(必背) <a class="header-anchor" href="#一、字母的含义-必背" aria-label="Permalink to &quot;一、字母的含义(必背)&quot;">​</a></h2><p>先记住每个字母代表什么:</p><table tabindex="0"><thead><tr><th>字母</th><th>含义</th></tr></thead><tbody><tr><td><strong>T</strong>(电源侧)</td><td>电源中性点<strong>直接接地</strong></td></tr><tr><td><strong>N</strong>(设备侧)</td><td>设备外壳<strong>接中性线</strong>(接零)</td></tr><tr><td><strong>I</strong></td><td>电源中性点<strong>不接地</strong>(或经阻抗接地)</td></tr><tr><td><strong>S</strong></td><td>保护零线与工作零线<strong>分开</strong></td></tr><tr><td><strong>C</strong></td><td>保护零线与工作零线<strong>合并</strong>(共用一根)</td></tr></tbody></table><p>读法:&quot;第一个字母 T/I 讲电源怎么接地,第二个字母 N/T 讲设备怎么保护&quot;。</p><h2 id="二、tn-系统-接零保护" tabindex="-1">二、TN 系统(接零保护) <a class="header-anchor" href="#二、tn-系统-接零保护" aria-label="Permalink to &quot;二、TN 系统(接零保护)&quot;">​</a></h2><p><strong>电源中性点直接接地,设备外壳接保护零线(PE 线)</strong>——最常见的系统。</p><p>按 N 线与 PE 线是否分开,分三种:</p><table tabindex="0"><thead><tr><th>形式</th><th>特点</th><th>说明</th></tr></thead><tbody><tr><td><strong>TN-C</strong></td><td>全系统 N 线与 PE 线<strong>合一</strong>,共用一根 <strong>PEN 线</strong></td><td>省钱,但三相不平衡时 PEN 线上有电流,外壳可能带电;三相负载均衡、有维护能力时用</td></tr><tr><td><strong>TN-S</strong></td><td>全系统 N 线与 PE 线<strong>分开</strong>(三相五线制)</td><td>最安全,PE 线平时无电流;现在新建低压配电普遍采用</td></tr><tr><td><strong>TN-C-S</strong></td><td>前段合(PEN),后段分开(N + PE)</td><td>从总配电箱处分开,应用较广</td></tr></tbody></table><blockquote><p>💡 记忆:<strong>TN-S 就是&quot;三相五线制&quot;</strong>(L1、L2、L3、N、PE 五根线),PE 线是保护接地线,平时没有电流流过,最安全。</p></blockquote><h2 id="三、tt-系统-独立接地保护" tabindex="-1">三、TT 系统(独立接地保护) <a class="header-anchor" href="#三、tt-系统-独立接地保护" aria-label="Permalink to &quot;三、TT 系统(独立接地保护)&quot;">​</a></h2><ul><li>电源中性点<strong>直接接地</strong>;</li><li>设备外壳<strong>单独直接接地</strong>(打自己的接地极),不接电源中性线。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>电源中性点 ──接地(工作接地)</span></span>
<span class="line"><span>设备外壳  ──接地(保护接地,独立)</span></span></code></pre></div><p>用于<strong>分散的、独立的用户</strong>(如农村、户外设备),好处是设备外壳与电源无直接电气联系;缺点是发生单相接地故障时,故障电流较小,要靠漏电保护器来跳闸保护。</p><h2 id="四、it-系统-中性点不接地" tabindex="-1">四、IT 系统(中性点不接地) <a class="header-anchor" href="#四、it-系统-中性点不接地" aria-label="Permalink to &quot;四、IT 系统(中性点不接地)&quot;">​</a></h2><ul><li>电源中性点<strong>不接地</strong>(或经高阻抗接地);</li><li>设备外壳直接接地。</li></ul><p>好处:<strong>第一次单相接地时,系统仍可继续运行</strong>(因为无接地回路,电流很小);多用于对供电连续性要求高的场所(如医院手术室、矿山)。但一相接地后,另外两相对地电压升高到线电压,<strong>存在隐患</strong>,要及时处理。</p><h2 id="五、三类系统对比与选择" tabindex="-1">五、三类系统对比与选择 <a class="header-anchor" href="#五、三类系统对比与选择" aria-label="Permalink to &quot;五、三类系统对比与选择&quot;">​</a></h2><table tabindex="0"><thead><tr><th>系统</th><th>电源中性点</th><th>设备保护</th><th>主要特点</th><th>常见场合</th></tr></thead><tbody><tr><td>TN</td><td>直接接地</td><td>接保护零线(PE)</td><td>故障电流大,保护动作快</td><td>城市电网、工厂、住宅(最常见)</td></tr><tr><td>TT</td><td>直接接地</td><td>独立接地</td><td>故障电流小,需漏电保护</td><td>分散用户、户外、农村</td></tr><tr><td>IT</td><td>不接地/经阻抗</td><td>直接接地</td><td>首此接地可继续运行</td><td>医院手术室、矿山、连续性要求高的场所</td></tr></tbody></table><blockquote><p>⚠️ <strong>保护方式与系统要匹配</strong>:TN 系统用<strong>接零保护</strong>,TT 系统用<strong>接地保护</strong>。在同一低压电网内,不允许一部分设备接零、一部分设备接地(否则接地设备漏电时,接零设备外壳会带电,很危险)。</p></blockquote><h2 id="六、考点提示" tabindex="-1">六、考点提示 <a class="header-anchor" href="#六、考点提示" aria-label="Permalink to &quot;六、考点提示&quot;">​</a></h2><ul><li>✅ 字母含义:T=直接接地,N=接零,S=分开,C=合并,I=不接地。</li><li>✅ <strong>TN-S = 三相五线制</strong>,PE 线平时无电流,最安全。</li><li>✅ 保护接零(TN)与保护接地(TT)不能混用在同一电网。</li><li>✅ IT 系统中性点不接地,首次接地故障可继续运行。</li><li>⚠️ 易混点:工作接地(电源中性点接地)vs 保护接地(设备外壳接地);N 线(工作零线)vs PE 线(保护零线)。</li></ul><h2 id="七、本节小结" tabindex="-1">七、本节小结 <a class="header-anchor" href="#七、本节小结" aria-label="Permalink to &quot;七、本节小结&quot;">​</a></h2><ul><li>系统分 TN、TT、IT 三大类,看电源中性点和设备外壳怎么接。</li><li>TN-S 是三相五线制,最常见最安全。</li><li>保护接零与保护接地不能在同一电网混用。</li></ul><h2 id="八、自测练习" tabindex="-1">八、自测练习 <a class="header-anchor" href="#八、自测练习" aria-label="Permalink to &quot;八、自测练习&quot;">​</a></h2><ol><li>(单选)TN-S 系统的 N 线与 PE 线()。 A. 合并　B. 全系统分开　C. 前段合并后段分开　D. 不设 PE 线</li><li>(判断)TN-S 系统就是三相五线制,PE 线平时没有电流通过。( )</li><li>(单选)电源中性点不接地的配电系统是()系统。 A. TN-C　B. TN-S　C. TT　D. IT</li><li>(判断)在同一低压电网中,可以一部分设备采用接零保护、一部分采用接地保护。( )</li><li>(单选)保护零线与工作零线在全系统分开的 TN 系统是()。 A. TN-C　B. TN-C-S　C. TN-S　D. IT</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>B</strong>。TN-S 全系统 N 线与 PE 线分开。</li><li><strong>√</strong>。PE 线平时无电流,是保护专用线。</li><li><strong>D</strong>。IT 系统电源中性点不接地。</li><li><strong>×</strong>。不允许混用,否则会引发危险。</li><li><strong>C</strong>。TN-S 是 N 线与 PE 线全系统分开的三相五线制。</li></ol></details>`,29)])])}const p=a(n,[["render",e]]);export{T as __pageData,p as default};
